-- 0320: An IDTA template is seeded with its nested elements.
--
-- The one template Aber knew was the Digital Nameplate, and its 20 top-level elements were typed into
-- 0002 by hand. Its nested collections were left out, and idta_submodel_templates cannot hold them: its
-- key is (template_id, id_short), and a nested idShort repeats from one collection to the next.
--
--   * idta_template_elements: one row for each element of a published IDTA submodel template, nested
--     ones included. It is keyed by the template and the element's path, which is the AAS API's
--     idShortPath (Markings[0].MarkingName). A row has the element's parent and its place in the document,
--     its model and value types, its semantic id and that id's type, the further semantic ids the template
--     gives it, how many its parent may hold, what the template says of it and the example it gives.
--   * Two templates: Digital Nameplate 3.0.3 (IDTA 02006), 36 elements, and Asset Interfaces Description
--     1.0.1 (IDTA 02017), 360. scripts/generate-idta-template.mjs writes the block below from the JSON kept
--     in scripts/vocabularies/, pinned by SHA-256, and scripts/check-idta-seed-sync.mjs checks it.
--   * idta_submodel_templates and its 20 rows are released and stay exactly as they are, with their
--     readers: the Nameplate dialog, the semantic id picker, concept_definitions and the AAS export.
--     Drift check 567 holds the two tables' top-level Nameplate elements to each other.
--   * concept_definitions gains no arm. A row's definition is what the template says of an element in
--     that template, such as a note on its format, and not a definition of the concept it cites.
--
-- ⚠ VERIFY. Read from admin-shell-io/submodel-templates at commit 5285185b (2026-10-29), whose licence
-- file is CC BY 4.0; nothing here was typed from the specifications' PDFs. The Nameplate file as IDTA
-- publishes it also carries 27 ConceptDescriptions whose text IEC CDD or ECLASS issued: the kept copy
-- leaves them out, so most Nameplate elements have no definition here. Asset Interfaces Description gives
-- "EMPTY" for its concepts' definitions, which is not one, and 12 of its elements no cardinality. The
-- Nameplate's AddressInformation has no elements inside it: the template takes them from IDTA's drop-in
-- of that name, which is in another template (IDTA 02002). Listing a template is not a conformance claim.
--
-- Reasoning: supabase/README.md, "An IDTA template is seeded with its nested elements (0320)". Idempotent.

-- -------------------------------------------------------------------------------------------------
-- 1. The table
-- -------------------------------------------------------------------------------------------------
-- Reference data, as idta_submodel_templates and vda5050_vocabulary are: a row is an element a template
-- defines, not a value a device holds. An id a row carries is issued by IDTA, IEC CDD, ECLASS or W3C.
CREATE TABLE IF NOT EXISTS public.idta_template_elements (
    template_id text NOT NULL,
    template_name text NOT NULL,
    template_number text NOT NULL,
    template_version text NOT NULL,
    path text NOT NULL,
    parent_path text,
    ordinal integer NOT NULL,
    id_short text,
    model_type text NOT NULL,
    value_type text,
    semantic_id text,
    semantic_id_type text,
    supplemental_semantic_ids text[] DEFAULT '{}'::text[] NOT NULL,
    cardinality text,
    definition text,
    example_value text,
    CONSTRAINT idta_template_elements_pkey PRIMARY KEY (template_id, path),
    -- A path is its parent's, then a dot and an idShort, or [n] for an item of a list.
    CONSTRAINT idta_template_elements_path_under_parent
        CHECK (((parent_path IS NULL) AND (strpos(path, '.'::text) = 0) AND (strpos(path, '['::text) = 0))
               OR ((parent_path IS NOT NULL)
                   AND ("left"(path, length(parent_path)) = parent_path)
                   AND (substr(path, length(parent_path) + 1) ~ '^([.][A-Za-z][A-Za-z0-9_-]*|[[][0-9]+[]])$'::text))),
    -- An item of a list has no idShort.
    CONSTRAINT idta_template_elements_id_short_shape
        CHECK (((id_short IS NULL) AND ("right"(path, 1) = ']'::text))
               OR ((id_short IS NOT NULL) AND (id_short ~ '^[A-Za-z][A-Za-z0-9_-]*$'::text))),
    CONSTRAINT idta_template_elements_ordinal_positive CHECK ((ordinal > 0)),
    CONSTRAINT idta_template_elements_model_type_valid
        CHECK ((model_type = ANY (ARRAY['AnnotatedRelationshipElement'::text, 'BasicEventElement'::text, 'Blob'::text,
                                        'Capability'::text, 'Entity'::text, 'File'::text, 'MultiLanguageProperty'::text,
                                        'Operation'::text, 'Property'::text, 'Range'::text, 'ReferenceElement'::text,
                                        'RelationshipElement'::text, 'SubmodelElementCollection'::text,
                                        'SubmodelElementList'::text]))),
    CONSTRAINT idta_template_elements_semantic_id_type_valid
        CHECK (((semantic_id IS NULL) AND (semantic_id_type IS NULL))
               OR ((semantic_id IS NOT NULL) AND (semantic_id_type IS NOT NULL)
                   AND (semantic_id_type = ANY (ARRAY['IRI'::text, 'IRDI'::text])))),
    CONSTRAINT idta_template_elements_supplemental_ids_shape
        CHECK ((array_position(supplemental_semantic_ids, NULL::text) IS NULL)),
    CONSTRAINT idta_template_elements_cardinality_valid
        CHECK ((cardinality = ANY (ARRAY['One'::text, 'ZeroToOne'::text, 'ZeroToMany'::text, 'OneToMany'::text])))
);

ALTER TABLE public.idta_template_elements OWNER TO postgres;
ALTER TABLE public.idta_template_elements ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.idta_template_elements IS
  'The elements of the IDTA submodel templates Aber seeds, nested ones included, generated from the '
  'templates'' own JSON (CC BY 4.0). Reference data, not deployment state: a row is an element a template '
  'defines. Listing a template claims no conformance to it. The Digital Nameplate''s top-level elements '
  'are also in idta_submodel_templates, which the Nameplate dialog and the AAS export read (0320).';
COMMENT ON COLUMN public.idta_template_elements.template_id IS
  'The template''s semantic id, which a submodel names to claim it: '
  'https://admin-shell.io/idta/nameplate/3/0/Nameplate (0320).';
COMMENT ON COLUMN public.idta_template_elements.template_number IS
  'IDTA''s number for the specification, such as IDTA 02006 (0320).';
COMMENT ON COLUMN public.idta_template_elements.template_version IS
  'The bug-fix release of the file the rows were read from, such as 3.0.3. The template_id names the '
  'major and minor version alone (0320).';
COMMENT ON COLUMN public.idta_template_elements.path IS
  'The element''s idShortPath, as the AAS API writes one: a dot into a collection, [n] into a list '
  '(Markings[0].MarkingName). A template''s [0] stands for each item of the list (0320).';
COMMENT ON COLUMN public.idta_template_elements.parent_path IS
  'The path of the element this one is inside. NULL at the top of the template (0320).';
COMMENT ON COLUMN public.idta_template_elements.ordinal IS
  'The element''s place in the template''s document, from 1, an element before what is inside it. So '
  'reading a template by ordinal gives each element under its parent (0320).';
COMMENT ON COLUMN public.idta_template_elements.id_short IS
  'The element''s idShort. NULL for an item of a list, which has none (0320).';
COMMENT ON COLUMN public.idta_template_elements.value_type IS
  'What the value is: a Property''s or a Range''s XSD type, the type of a list''s items, or the content '
  'type the template gives a File. NULL for the other model types (0320).';
COMMENT ON COLUMN public.idta_template_elements.semantic_id IS
  'The id the template gives the element, issued by IDTA, IEC CDD, ECLASS or W3C and never minted here. '
  'NULL where the template gives none (0320).';
COMMENT ON COLUMN public.idta_template_elements.supplemental_semantic_ids IS
  'The further ids the template gives the element, such as the ECLASS IRDI beside an IEC CDD one. Empty '
  'for none (0320).';
COMMENT ON COLUMN public.idta_template_elements.cardinality IS
  'How many of the element its parent holds: One, ZeroToOne, ZeroToMany or OneToMany. NULL where the '
  'template does not say (0320).';
COMMENT ON COLUMN public.idta_template_elements.definition IS
  'What the template''s own file says of the element, in English: its concept''s definition where IDTA '
  'wrote it, the element''s description and its constraint. NULL where that is nothing. Never an IEC CDD or '
  'ECLASS text (0320).';
COMMENT ON COLUMN public.idta_template_elements.example_value IS
  'The example the template gives for the element''s value. NULL for none (0320).';

-- Anyone signed in reads it. Nobody writes it: the generated rows below are the only writer, and
-- run as the owner. anon is revoked by name.
REVOKE ALL ON TABLE public.idta_template_elements FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.idta_template_elements TO authenticated, service_role;

SELECT public.replay_policy('public.idta_template_elements', 'idta_template_elements_select_authenticated', $ddl$
CREATE POLICY idta_template_elements_select_authenticated ON public.idta_template_elements FOR SELECT TO authenticated USING (true);
$ddl$);

